python3 -I -c '
import sys, re, zipfile
from xml.etree import ElementTree as ET
W = "{http://schemas.openxmlformats.org/wordprocessingml/2006/main}"
z = zipfile.ZipFile(sys.argv[1])
print("PARTS:", ", ".join(z.namelist()))
def ptext(p):
    out = []
    for el in p.iter():
        if el.tag == W + "t":
            out.append(el.text or "")
        elif el.tag == W + "tab":
            out.append("\t")
        elif el.tag in (W + "br", W + "cr"):
            out.append("\n")
    return "".join(out)
def pprefix(p):
    ppr = p.find(W + "pPr")
    pre = ""
    if ppr is not None:
        st = ppr.find(W + "pStyle")
        if st is not None:
            pre += "[" + st.get(W + "val", "") + "] "
        if ppr.find(W + "numPr") is not None:
            pre += "* "
    return pre
root = ET.fromstring(z.read("word/document.xml"))
body = root.find(W + "body")
for child in body:
    if child.tag == W + "p":
        t = ptext(child)
        if t.strip():
            print(pprefix(child) + t)
    elif child.tag == W + "tbl":
        for tr in child.iter(W + "tr"):
            cells = []
            for tc in tr.findall(W + "tc"):
                cells.append(" / ".join(ptext(p) for p in tc.iter(W + "p") if ptext(p).strip()))
            print("| " + " | ".join(cells) + " |")
for name in z.namelist():
    if re.fullmatch(r"word/(comments|footnotes|endnotes|header\d*|footer\d*)\.xml", name):
        r = ET.fromstring(z.read(name))
        lines = [ptext(p) for p in r.iter(W + "p")]
        lines = [l for l in lines if l.strip()]
        if lines:
            print("== " + name)
            print("\n".join(lines))
