const fs = require('node:fs');
const SRC = '/Users/laptop/mprojects/ahmad-sheraz-calculator/src/';
const { viewModel } = require(SRC + 'viewmodel.js');
const OUT = process.argv[2];

function makeRng(seed) {
  let state = seed >>> 0;
  function next() {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return (t ^ (t >>> 14)) >>> 0;
  }
  return { next, int(min, max) { return min + (next() % (max - min + 1)); } };
}

const rng = makeRng(20260101);
const BLANKS = ['', '', '', ' ', '\t', ' ', ' \t '];
const pick = (list) => list[rng.int(0, list.length - 1)];
const quotient = (a, b) => (a - (a % b)) / b;
const pad2 = (n) => (n < 10 ? '0' : '') + String(n);
const hundredthsText = (n) => String(quotient(n, 100)) + '.' + pad2(n % 100);
const spell = (text) => pick(BLANKS) + (rng.int(0, 3) === 0 ? '00' : '') + text + pick(BLANKS);

const lines = [];
function addCase(billCents, bp, people) {
  const entries = { bill: spell(hundredthsText(billCents)), tip: spell(hundredthsText(bp)), people: spell(String(people)) };
  lines.push(JSON.stringify({ billCents, bp, people, entries, view: viewModel(entries) }));
}

for (let i = 0; i < 150000; i += 1) {
  const mode = rng.int(0, 5);
  const billCents = mode === 0 ? rng.int(1, 300) : mode === 1 ? 100000000 - rng.int(0, 300) : rng.int(1, 100000000);
  addCase(billCents, rng.int(0, 10000), rng.int(1, 50));
}

let ties = 0;
for (let bill = 1; bill <= 30000; bill += 1) {
  for (let bp = 0; bp <= 10000; bp += 1) {
    if ((bill * bp) % 10000 === 5000) {
      addCase(bill, bp, rng.int(1, 50));
      ties += 1;
    }
  }
}

fs.writeFileSync(OUT, lines.join('\n') + '\n');
console.log('cases written:', lines.length, '| exact half-cent ties among them:', ties);

