import os
import re
import shutil
import subprocess

root = os.getcwd()
base = "/private/tmp/claude-501/-Users-laptop-mprojects-ahmad-sheraz-calculator/7ff1f359-911c-4f25-90f7-f2ad39b0744b/scratchpad/hostile"


def copy_project(target):
    os.makedirs(target)
    for item in ("src", "tests", "docs", "package.json"):
        source = os.path.join(root, item)
        destination = os.path.join(target, item)
        if os.path.isdir(source):
            shutil.copytree(source, destination)
        else:
            shutil.copy2(source, destination)


def to_crlf(folder):
    for current, _, files in os.walk(folder):
        for name in files:
            path = os.path.join(current, name)
            data = open(path, "rb").read()
            if b"\r\n" not in data:
                open(path, "wb").write(data.replace(b"\n", b"\r\n"))


def run(label, folder):
    done = subprocess.run(["npm", "test"], cwd=folder, capture_output=True, text=True)
    out = done.stdout + done.stderr
    counts = dict(re.findall(r"^ℹ (tests|pass|fail) (\d+)", out, re.M))
    print(f"{label}: exit {done.returncode}, tests {counts.get('tests')}, pass {counts.get('pass')}, fail {counts.get('fail')}")
    seen = []
    for line in out.splitlines():
        if line.startswith("✖ ") and not line.startswith("✖ failing tests:"):
            title = re.sub(r" \([0-9.]+ms\)$", "", line)
            if title not in seen:
                seen.append(title)
    for title in seen:
        print("    " + title[:140])


crlf = os.path.join(base, "crlf-copy")
copy_project(crlf)
to_crlf(crlf)
run("copy with Windows line endings (CRLF)", crlf)

spaced = os.path.join(base, "folder with spaces", "tip-bill-splitter")
copy_project(spaced)
run("copy in a folder whose path contains spaces", spaced)

