(function () {
  const g = (id) => document.getElementById(id);
  const names = ['bill', 'tip', 'people'];
  const inputs = { bill: g('bill'), tip: g('tip'), people: g('people') };
  const fire = (el) => el.dispatchEvent(new Event('input', { bubbles: true }));
  let seed = 987654321;
  const rnd = (n) => { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return seed % n; };
  const pick = (list) => list[rnd(list.length)];
  const LISTS = {
    bill: ['', '0', '0.', '.', '.5', '5.', '100', '42.50', '999999.99', '1000000.00', '1000000.01', 'abc', '1,5', '12,50', '10.005', '  7  ', '0.01', '1e3', '٣', '99999999999999999999', '12.34', '100.00', '0.30', '10.05', '42.50 ', '​5', '-5', '+5', '0.005'],
    tip: ['', '0', '15', '18', '7.25', '100', '100.01', 'abc', '12.505', '.5', '5.', '1e1', '20', '12.5', '0.01', '15%', ' 15 ', '-1'],
    people: ['', '0', '1', '2', '3', '7', '49', '50', '51', '2.5', 'abc', '04', ' 4 ', '2.0', '2.', '1e1', '٤']
  };
  const trimBlanks = (s) => s.replace(/^[ \t ]+|[ \t ]+$/g, '');
  const cents = (t) => { const [w, f] = t.split('.'); return Number(w) * 100 + Number(f); };
  const entries = { bill: '', tip: '15', people: '2' };
  const failures = [];
  const stats = { steps: 0, resets: 0, withResult: 0, withMessages: 0, quiet: 0 };
  function fail(step, what, extra) { failures.push({ step, what, entries: { ...entries }, extra }); }

  function check(step, afterReset) {
    const msgs = names.map((n) => g(n + '-message').textContent);
    const inv = names.map((n) => inputs[n].getAttribute('aria-invalid'));
    const hidden = g('result').hidden;
    const tip = g('result-tip').textContent, total = g('result-total').textContent, note = g('result-note').textContent;
    const shares = [...document.querySelectorAll('#result-shares li')].map((li) => li.textContent);
    const anyMsg = msgs.some((m) => m !== '');
    names.forEach((n, i) => { if ((msgs[i] !== '') !== (inv[i] === 'true')) fail(step, 'aria-invalid disagrees with the message', { n, msg: msgs[i], inv: inv[i] }); });
    if (anyMsg && !hidden) fail(step, 'a result is visible together with a message');
    if (hidden && (tip !== '' || total !== '' || note !== '' || shares.length !== 0)) fail(step, 'old amounts left in the hidden Result box', { tip, total, note, shares });
    if (!hidden) {
      const sum = shares.reduce((a, s) => a + cents(s), 0);
      if (sum !== cents(total)) fail(step, 'shares do not add up to the total', { shares, total });
      if (shares.length !== Number(trimBlanks(inputs.people.value))) fail(step, 'number of shares differs from People', { n: shares.length });
      if (/NaN|Infinity|undefined|[0-9][eE][+-]?[0-9]/.test(tip + total + note + shares.join(' '))) fail(step, 'forbidden text on the page');
      if (!(cents(total) >= cents(tip))) fail(step, 'total smaller than the tip');
    }
    names.forEach((n) => { if (inputs[n].value !== entries[n]) fail(step, 'a field value is not what was entered', { n, value: inputs[n].value }); });
    const expected = TipSplit.viewmodel.viewModel(entries);
    names.forEach((n, i) => { if (msgs[i] !== expected.fields[n].message) fail(step, 'page message differs from the view-model', { n, page: msgs[i], vm: expected.fields[n].message }); });
    if ((expected.result === null) !== hidden) fail(step, 'Result box visibility differs from the view-model');
    if (expected.result && (expected.result.tip !== tip || expected.result.total !== total || expected.result.note !== note || expected.result.shares.join('|') !== shares.join('|'))) fail(step, 'page amounts differ from the view-model');
    if (afterReset) {
      if (document.activeElement !== inputs.bill) fail(step, 'focus is not on Bill after Reset', { active: document.activeElement.id });
      if (anyMsg) fail(step, 'a message is left after Reset');
    }
    anyMsg ? (stats.withMessages += 1) : (hidden ? (stats.quiet += 1) : (stats.withResult += 1));
  }

  for (let step = 0; step < 8000; step += 1) {
    stats.steps += 1;
    if (rnd(9) === 0) {
      g('reset').click();
      entries.bill = ''; entries.tip = '15'; entries.people = '2';
      stats.resets += 1;
      check(step, true);
    } else {
      const name = pick(names);
      const value = pick(LISTS[name]);
      entries[name] = value;
      inputs[name].value = value;
      fire(inputs[name]);
      check(step, false);
    }
  }
  return JSON.stringify({ stats, failureCount: failures.length, firstFailures: failures.slice(0, 4) });
})()

