};

function makePage(requested) {
  const elements = {};
  const page = {
    activeElement: null,
    getElementById(id) {
      requested.push(id);
      return elements[id] === undefined ? null : elements[id];
    },
    createElement() {
      return makeElement();
    }
  };

  function makeElement() {
    const listeners = {};
    const attributes = {};
    let text = '';
    const element = {
      value: '',
      hidden: false,
      children: [],
      get textContent() {
        return element.children.length > 0 ? element.children.map((child) => child.textContent).join('') : text;
      },
      set textContent(value) {
        text = String(value);
        element.children = [];
      },
      setAttribute(name, value) {
        attributes[name] = String(value);
      },
      getAttribute(name) {
        return name in attributes ? attributes[name] : null;
      },
      addEventListener(type, handler) {
        (listeners[type] = listeners[type] || []).push(handler);
      },
      appendChild(child) {
        element.children.push(child);
        return child;
      },
      focus() {
        page.activeElement = element;
      },
      fire(type) {
        (listeners[type] || []).forEach((handler) => handler({ type, target: element }));
      }
    };
    return element;
  }

  for (const id of PAGE_IDS) {
