76	function criterionIds() {
77	  return [...stories.matchAll(/^- (S-\d+\.\d+) /gm)].map((match) => match[1]);
78	}
79	
80	function testNames() {
81	  const names = [];
82	  for (const file of fs.readdirSync(TEST_DIR)) {
83	    if (!file.endsWith('.test.js')) {
84	      continue;
85	    }
86	    const source = fs.readFileSync(path.join(TEST_DIR, file), 'utf8');
87	    const calls = (source.match(/^test\(/gm) || []).length;
88	    const named = [...source.matchAll(/^test\(\s*'([^'\n]*)'/gm)].map((match) => match[1]);
89	    assert.equal(named.length, calls, `${file}: every top-level test call needs a single-quoted name`);
90	    names.push(...named);
91	  }
92	  return names;
93	}
94	
95	function testedIds() {
96	  return testNames()
97	    .map((name) => /^(S-\d+\.\d+)[ :]/.exec(name))
98	    .filter((match) => match !== null)
99	    .map((match) => match[1]);
100	}
101	
102	test('DOCS-3 every test name starts with a criterion id from the docs, DOCS- or PAGE-', () => {
103	  const ids = new Set(criterionIds());
104	  for (const name of testNames()) {
105	    if (name.startsWith('DOCS-') || name.startsWith('PAGE-')) {
106	      continue;
107	    }
108	    const match = /^(S-\d+\.\d+)[ :]/.exec(name);
109	    assert.ok(match !== null, `test name does not start with a criterion id: ${name}`);
110	    assert.ok(ids.has(match[1]), `test name uses ${match[1]}, which is not in the stories doc: ${name}`);
111	  }
112	});
113	
114	test('DOCS-4 every criterion has a test, is on the manual list or is on the not-built list', () => {
115	  const ids = criterionIds();
116	  const tested = new Set(testedIds());
117	  for (const id of ids) {
118	    assert.ok(tested.has(id) || MANUAL.includes(id) || NOT_BUILT.includes(id), `${id} has no test and is on neither list`);
119	  }
120	  for (const id of [...MANUAL, ...NOT_BUILT]) {
121	    assert.ok(ids.includes(id), `${id} is on a list but is not in the stories doc`);
122	  }
123	  for (const id of MANUAL) {
124	    assert.ok(!NOT_BUILT.includes(id), `${id} is on both lists`);
125	  }
126	});
127	
128	test('DOCS-5 the not-built criteria have no tests', () => {
129	  const tested = new Set(testedIds());
130	  for (const id of NOT_BUILT) {
131	    assert.ok(!tested.has(id), `${id} is not built but has a test`);
132	  }
133	});
134	
135	test('DOCS-6 every message in messages.js has a test in messages.test.js', () => {
136	  const source = read('tests', 'messages.test.js');
137	  const literals = [...source.matchAll(/'([^'\n]*)'/g)].map((match) => match[1]);
138	  const { fixed, templates } = messageTexts();
139	  for (const text of fixed) {
140	    assert.ok(literals.includes(text), `no message test for: ${text}`);
141	  }
142	  for (const template of templates) {
143	    assert.ok(literals.some((text) => matchesTemplate(template, text)), `no message test for: ${template}`);
144	  }
145	});
146	
147	test('DOCS-7 the traceability table matches the story headings, the jobs and the role', () => {
148	  const jobs = read('docs', 'jobs-to-be-done.md');
149	  const roles = read('docs', 'app-roles.md');
150	  const headings = [...stories.matchAll(/^## (S-\d+) \(serves (J-\d+), (?:Implemented|Not implemented)\): /gm)]
151	    .map((match) => [match[1], match[2]]);
152	  const rows = [...stories.matchAll(/^\| (S-\d+) \| (J-\d+) \| (.+?) \|$/gm)]
153	    .map((match) => [match[1], match[2], match[3]]);
154	  assert.ok(headings.length > 0, 'no story headings found');
155	  assert.deepEqual(rows.map(([story, job]) => [story, job]), headings);
156	  const jobRoles = new Map([...jobs.matchAll(/^## (J-\d+) \((.+?)\): /gm)].map((match) => [match[1], match[2]]));
157	  const roleNames = [...roles.matchAll(/^## (.+)$/gm)].map((match) => match[1]);
158	  for (const [story, job, role] of rows) {
159	    assert.equal(jobRoles.get(job), role, `${story}: job ${job} belongs to a different role`);
160	    assert.ok(roleNames.includes(role), `${story}: role ${role} is not in the roles doc`);
161	  }
162	});
