164	test('DOCS-8 the limits written in the messages match LIMITS', () => {
165	  function hundredths(text) {
166	    const [whole, fraction = ''] = text.split('.');
167	    return Number(whole) * 100 + Number((fraction + '00').slice(0, 2));
168	  }
169	  assert.equal(hundredths(/at least ([0-9.]+)\./.exec(messages.bill.min)[1]), LIMITS.billMinCents);
170	  assert.equal(hundredths(/more than ([0-9.]+)\./.exec(messages.bill.max)[1]), LIMITS.billMaxCents);
171	  assert.equal(Number(/more than ([0-9]+)%/.exec(messages.tip.max)[1]) * 100, LIMITS.tipMaxBasisPoints);
172	  assert.equal(Number(/at least ([0-9]+) person/.exec(messages.people.min)[1]), LIMITS.peopleMin);
173	  assert.equal(Number(/at most ([0-9]+) people/.exec(messages.people.max)[1]), LIMITS.peopleMax);
174	});
175	
176	test('DOCS-9 every story has a valid status, and a status note naming its own criteria unless it is Implemented', () => {
177	  const sections = stories.split(/^## /m).slice(1).filter((section) => /^S-\d+ /.test(section));
178	  assert.ok(sections.length > 0, 'no stories found');
179	  for (const section of sections) {
180	    const heading = /^(S-\d+) \(serves (J-\d+), (Implemented|Not implemented)\): /.exec(section);
181	    assert.ok(heading !== null, `bad story heading: ${section.split('\n')[0]}`);
182	    const story = heading[1];
183	    const own = [...section.matchAll(new RegExp('^- (' + story + '\\.\\d+) ', 'gm'))].map((match) => match[1]);
184	    const note = /^Status note: (.*)$/m.exec(section);
185	    if (heading[3] === 'Implemented') {
186	      assert.equal(note, null, `${story} is Implemented but has a status note`);
187	      for (const id of own) {
188	        assert.ok(!NOT_BUILT.includes(id), `${story} is Implemented but ${id} is not built`);
189	      }
190	    } else {
191	      assert.ok(note !== null, `${story} is Not implemented but has no status note`);
192	      const named = [...note[1].matchAll(/S-\d+\.\d+/g)].map((match) => match[0]);
193	      assert.ok(named.length > 0, `${story}: the status note names no criteria`);
194	      for (const id of named) {
195	        assert.ok(own.includes(id), `${story}: the status note names ${id}, which is not one of its criteria`);
196	      }
197	    }
198	  }
199	});
200	
201	function storySections() {
202	  return stories.split(/^## /m).slice(1).filter((section) => /^S-\d+ /.test(section));
203	}
204	
205	function ownCriteria(section, story) {
206	  return [...section.matchAll(new RegExp('^- (' + story + '\\.\\d+) ', 'gm'))].map((match) => match[1]);
207	}
208	
209	// "S-4.1 to S-4.14 and S-4.16" gives S-4.1 up to S-4.14, and S-4.16.
210	function namedIds(text) {
211	  const ids = [];
212	  for (const match of text.matchAll(/(S-\d+)\.(\d+)(?: to (S-\d+)\.(\d+))?/g)) {
213	    const first = Number(match[2]);
214	    const last = match[3] === undefined ? first : Number(match[4]);
215	    for (let n = first; n <= last; n += 1) {
216	      ids.push(`${match[1]}.${n}`);
217	    }
218	  }
219	  return ids;
220	}
221	
222	function reportRows() {
223	  const rows = new Map();
224	  for (const line of read('docs', 'test-report.md').split('\n')) {
225	    const match = /^\| (S-\d+\.\d+) \| (.+) \| (pass|fail|not confirmed|not built) \|$/.exec(line);
226	    if (match) {
227	      rows.set(match[1], { how: match[2], result: match[3] });
228	    }
229	  }
230	  return rows;
231	}
232	
233	test('DOCS-10 every status matches the evidence in the test report', () => {
234	  const rows = reportRows();
235	  for (const section of storySections()) {
236	    const heading = /^(S-\d+) \(serves (J-\d+), (Implemented|Not implemented)\): /.exec(section);
237	    const story = heading[1];
238	    const own = ownCriteria(section, story);
239	    const unproven = own.filter((id) => !(rows.has(id) && rows.get(id).result === 'pass'));
240	    if (heading[3] === 'Implemented') {
241	      assert.deepEqual(unproven, [], `${story} is Implemented but these criteria do not pass in the test report: ${unproven.join(', ')}`);
242	    } else {
243	      assert.ok(unproven.length > 0, `${story} is Not implemented but every criterion passes in the test report`);
244	      const note = /^Status note: (.*)$/m.exec(section);
245	      assert.deepEqual(namedIds(note[1]), unproven, `${story}: the status note must name exactly the criteria without evidence`);
246	    }
247	  }
248	});
249	
250	test('DOCS-11 the test report has one row per criterion, naming a real test or the manual check', () => {
251	  const rows = reportRows();
252	  const ids = criterionIds();
253	  assert.deepEqual([...rows.keys()], ids, 'the report rows must be the criteria, in the order of the stories doc');
254	  const names = testNames();
255	  for (const id of ids) {
256	    const { how, result } = rows.get(id);
257	    if (NOT_BUILT.includes(id)) {
258	      assert.equal(how, 'none, not built', `${id}: how verified`);
259	      assert.equal(result, 'not built', `${id}: result`);
260	    } else if (MANUAL.includes(id)) {
261	      const confirmed = how === 'manual, confirmed by me' && (result === 'pass' || result === 'fail');
262	      const unconfirmed = how === 'manual, not confirmed' && result === 'not confirmed';
263	      assert.ok(confirmed || unconfirmed, `${id}: a manual row says "manual, confirmed by me" with pass or fail, or "manual, not confirmed" with not confirmed`);
264	    } else {
265	      assert.ok(result === 'pass' || result === 'fail', `${id}: an automated row says pass or fail`);
266	      for (const name of how.split('; ')) {
267	        assert.ok(names.includes(name), `${id}: no test is named "${name}"`);
268	        assert.ok(name.startsWith(id + ' '), `${id}: the test "${name}" does not start with this criterion id`);
269	      }
270	    }
271	  }
272	});
273	
274	test('DOCS-12 every Implemented story says what it rests on, and says the automated tests never load the page', () => {
275	  for (const section of storySections()) {
276	    const heading = /^(S-\d+) \(serves (J-\d+), (Implemented|Not implemented)\): /.exec(section);
277	    if (heading[3] !== 'Implemented') {
278	      continue;
279	    }
280	    const story = heading[1];
281	    const own = ownCriteria(section, story);
282	    const evidence = /^Evidence: (.*)$/m.exec(section);
283	    assert.ok(evidence !== null, `${story} is Implemented but has no Evidence line`);
284	    const covered = [];
285	    for (const part of evidence[1].replace(/\.$/, '').split('; ')) {
286	      const ids = namedIds(part);
287	      if (part.includes('by a manual check')) {
288	        assert.ok(ids.every((id) => MANUAL.includes(id)), `${story}: "${part}" puts a criterion that is not on the manual list under the manual check`);
289	      } else {
290	        assert.ok(part.includes('by automated tests only, which never load the page'), `${story}: "${part}" must say it rests on automated tests only, which never load the page`);
291	        assert.ok(ids.every((id) => !MANUAL.includes(id)), `${story}: "${part}" puts a manual-list criterion under automated tests only`);
292	      }
293	      covered.push(...ids);
294	    }
295	    assert.deepEqual([...covered].sort(), [...own].sort(), `${story}: the Evidence line must name every criterion once`);
296	  }
297	});
